<?php require 'config/db.php';require 'includes/auth.php';require_login();$page_title='Response Teams';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['ADMIN','OPERATOR']);check_csrf();$s=$pdo->prepare('UPDATE response_teams SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['id']]);audit($pdo,'Team status changed','Team #'.(int)$_POST['id'].' to '.$_POST['status']);$_SESSION['flash']='Team status updated.';header('Location:teams.php');exit;}$rows=$pdo->query('SELECT * FROM response_teams ORDER BY id')->fetchAll();require 'includes/header.php';?><section class="panel"><h2>Response Teams</h2><div class="tablewrap"><table><tr><th>Team</th><th>Department</th><th>Contact</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['team_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['contact'])?></td><td><?=e($r['status'])?></td><td><?php if(can_write()):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option <?=$r['status']==='Available'?'selected':''?>>Available</option><option <?=$r['status']==='Busy'?'selected':''?>>Busy</option><option <?=$r['status']==='Offline'?'selected':''?>>Offline</option></select><button class="smallbtn">Update</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
